insert into exercises (slug, name_pt, family, primary_muscle, secondary_muscles, equipment, pegada, largura_pegada, acessorio, padrao_movimento, default_load_form, description_pt, source, source_ref, license, attribution)
values
    ('supino_reto_barra', 'Supino reto com barra', 'supino_reto', 'peito', array['triceps', 'ombro_anterior']::text[], 'barra', 'pronada', 'media', null, 'empurrar_horizontal', 'total', 'Deitado no banco reto, pés firmes no chão e escápulas encaixadas para trás, segure a barra um pouco além da largura dos ombros. Desça controlando até a barra tocar a linha do peito e empurre de volta até estender os cotovelos. Erros comuns: quicar a barra no peito, tirar o quadril do banco e abrir os cotovelos a 90 graus do tronco.', 'proprio', null, 'proprio', null),
    ('supino_reto_halteres', 'Supino reto com halteres', 'supino_reto', 'peito', array['triceps', 'ombro_anterior']::text[], 'halteres', null, null, null, 'empurrar_horizontal', 'por_halter', 'Deitado no banco reto com um halter em cada mão, punhos alinhados sobre os cotovelos. Desça os halteres ao lado do peito até sentir alongar e empurre para cima aproximando-os sem bater. Evite descer além do conforto do ombro e perder o encaixe das escápulas.', 'proprio', null, 'proprio', null),
    ('supino_inclinado_barra', 'Supino inclinado com barra', 'supino_inclinado', 'peito', array['ombro_anterior', 'triceps']::text[], 'barra', 'pronada', 'media', null, 'empurrar_horizontal', 'total', 'No banco inclinado entre 30 e 45 graus, segure a barra pouco além da largura dos ombros. Desça até a parte alta do peito e empurre de volta na mesma linha. Banco inclinado demais transfere o trabalho para o ombro; mantenha o quadril no banco.', 'proprio', null, 'proprio', null),
    ('supino_inclinado_halteres', 'Supino inclinado com halteres', 'supino_inclinado', 'peito', array['ombro_anterior', 'triceps']::text[], 'halteres', null, null, null, 'empurrar_horizontal', 'por_halter', 'No banco inclinado entre 30 e 45 graus, comece com os halteres acima do peito. Desça ao lado da parte alta do peito e empurre de volta aproximando os halteres. Evite arquear demais a lombar para transformar o movimento em supino reto.', 'proprio', null, 'proprio', null),
    ('supino_declinado_barra', 'Supino declinado com barra', 'supino_declinado', 'peito', array['triceps', 'ombro_anterior']::text[], 'barra', 'pronada', 'media', null, 'empurrar_horizontal', 'total', 'No banco declinado com as pernas presas no apoio, segure a barra na largura do supino reto. Desça até a parte baixa do peito e empurre de volta. Peça ajuda para tirar e devolver a barra, porque a posição dificulta o encaixe no suporte.', 'proprio', null, 'proprio', null),
    ('supino_declinado_halteres', 'Supino declinado com halteres', 'supino_declinado', 'peito', array['triceps', 'ombro_anterior']::text[], 'halteres', null, null, null, 'empurrar_horizontal', 'por_halter', 'No banco declinado com as pernas presas, comece com os halteres acima da parte baixa do peito. Desça ao lado do tronco e empurre de volta. Controle a descida, já que sair do banco com halteres pesados é mais difícil nessa posição.', 'proprio', null, 'proprio', null),
    ('supino_reto_smith', 'Supino reto no smith', 'supino_reto', 'peito', array['triceps', 'ombro_anterior']::text[], 'maquina', null, null, null, 'empurrar_horizontal', 'total', 'Deitado no banco reto sob a barra guiada, ajuste o banco para a barra descer na linha do peito. Destrave, desça controlando e empurre até estender os cotovelos. Banco mal posicionado faz a barra bater no pescoço ou na barriga.', 'proprio', null, 'proprio', null),
    ('supino_inclinado_smith', 'Supino inclinado no smith', 'supino_inclinado', 'peito', array['ombro_anterior', 'triceps']::text[], 'maquina', null, null, null, 'empurrar_horizontal', 'total', 'No banco inclinado sob a barra guiada, ajuste a posição para a barra descer na parte alta do peito. Desça controlando e empurre de volta. Confira a trava antes de começar e antes de soltar a barra.', 'proprio', null, 'proprio', null),
    ('supino_vertical_maquina', 'Supino vertical na máquina', 'supino_maquina', 'peito', array['triceps', 'ombro_anterior']::text[], 'maquina', null, null, null, 'empurrar_horizontal', 'total', 'Sentado na máquina com as costas apoiadas, ajuste o banco para as pegadas ficarem na altura do meio do peito. Empurre para frente até quase estender os cotovelos e volte devagar até sentir o peito alongar. Evite tirar as costas do encosto e encolher os ombros no empurrão.', 'proprio', null, 'proprio', null),
    ('supino_inclinado_maquina', 'Supino inclinado na máquina', 'supino_maquina', 'peito', array['ombro_anterior', 'triceps']::text[], 'maquina', null, null, null, 'empurrar_horizontal', 'total', 'Sentado na máquina de supino inclinado, ajuste o banco para as pegadas ficarem na altura da parte alta do peito. Empurre para cima e para frente e volte controlando. Mantenha as escápulas apoiadas no encosto durante toda a série.', 'proprio', null, 'proprio', null),
    ('supino_reto_pegada_fechada', 'Supino reto com pegada fechada', 'supino_reto', 'triceps', array['peito', 'ombro_anterior']::text[], 'barra', 'pronada', 'fechada', null, 'empurrar_horizontal', 'total', 'Deitado no banco reto, segure a barra com as mãos na largura dos ombros ou um pouco menos. Desça com os cotovelos próximos ao tronco até a parte baixa do peito e empurre de volta. Pegada estreita demais força o punho sem ganho para o tríceps.', 'proprio', null, 'proprio', null),
    ('crucifixo_reto_halteres', 'Crucifixo reto com halteres', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'halteres', null, null, null, 'empurrar_horizontal', 'por_halter', 'Deitado no banco reto, halteres acima do peito com os cotovelos levemente dobrados. Abra os braços em arco até sentir o peito alongar e volte pelo mesmo caminho. Dobrar e esticar os cotovelos durante o movimento transforma o exercício em supino.', 'proprio', null, 'proprio', null),
    ('crucifixo_inclinado_halteres', 'Crucifixo inclinado com halteres', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'halteres', null, null, null, 'empurrar_horizontal', 'por_halter', 'No banco inclinado entre 30 e 45 graus, halteres acima do peito e cotovelos levemente dobrados. Abra os braços em arco até alongar a parte alta do peito e feche de volta. Não deixe os halteres descerem abaixo da linha do ombro.', 'proprio', null, 'proprio', null),
    ('peck_deck', 'Peck deck (voador)', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'maquina', null, null, null, 'empurrar_horizontal', 'total', 'Sentado com as costas apoiadas, ajuste o banco para os braços ficarem na altura do peito. Feche os braços à frente do corpo contraindo o peito e volte devagar até alongar. Evite encolher os ombros e soltar o peso de uma vez na volta.', 'proprio', null, 'proprio', null),
    ('crossover_polia_alta', 'Crossover na polia alta', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'cabo', null, null, null, 'empurrar_horizontal', 'total', 'Em pé no meio do crossover, segure as alças das polias altas com o tronco levemente inclinado à frente. Traga as mãos para baixo e à frente do quadril num arco, cotovelos levemente dobrados, e volte controlando. Não use o peso do corpo para puxar.', 'proprio', null, 'proprio', null),
    ('crossover_polia_baixa', 'Crossover na polia baixa', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'cabo', null, null, null, 'empurrar_horizontal', 'total', 'Em pé no meio do crossover, segure as alças das polias baixas. Suba as mãos num arco até a altura do peito ou do queixo, cotovelos levemente dobrados, e volte devagar. Ênfase na parte alta do peito; evite jogar o tronco para trás.', 'proprio', null, 'proprio', null),
    ('crossover_polia_media', 'Crossover na polia média', 'crucifixo', 'peito', array['ombro_anterior']::text[], 'cabo', null, null, null, 'empurrar_horizontal', 'total', 'Com as polias na altura do peito, segure as alças e dê um passo à frente. Feche os braços à frente do peito num arco horizontal e volte controlando. Mantenha os cotovelos fixos levemente dobrados.', 'proprio', null, 'proprio', null),
    ('flexao_bracos', 'Flexão de braços', 'flexao', 'peito', array['triceps', 'ombro_anterior', 'abdomen']::text[], 'peso_corporal', null, null, null, 'empurrar_horizontal', 'peso_corporal', 'Em prancha alta com as mãos pouco além da largura dos ombros, corpo alinhado da cabeça aos calcanhares. Desça até o peito quase tocar o chão e empurre de volta. Erros comuns: deixar o quadril cair e abrir os cotovelos demais.', 'proprio', null, 'proprio', null),
    ('flexao_bracos_inclinada', 'Flexão de braços inclinada', 'flexao', 'peito', array['triceps', 'ombro_anterior']::text[], 'peso_corporal', null, null, null, 'empurrar_horizontal', 'peso_corporal', 'Com as mãos apoiadas num banco ou banco de step e o corpo alinhado, desça o peito até a borda do apoio e empurre de volta. Quanto mais alto o apoio, mais fácil a flexão. Mantenha o abdômen firme para o quadril não cair.', 'proprio', null, 'proprio', null),
    ('flexao_bracos_declinada', 'Flexão de braços declinada', 'flexao', 'peito', array['ombro_anterior', 'triceps']::text[], 'peso_corporal', null, null, null, 'empurrar_horizontal', 'peso_corporal', 'Com os pés apoiados num banco e as mãos no chão, corpo alinhado. Desça até o peito quase tocar o chão e empurre de volta. A inclinação aumenta a carga e o trabalho da parte alta do peito e do ombro.', 'proprio', null, 'proprio', null),
    ('flexao_diamante', 'Flexão diamante', 'flexao', 'triceps', array['peito', 'ombro_anterior']::text[], 'peso_corporal', null, null, null, 'empurrar_horizontal', 'peso_corporal', 'Em prancha alta com as mãos juntas sob o peito, polegares e indicadores formando um losango. Desça com os cotovelos junto ao tronco e empurre de volta. Se o punho incomodar, afaste um pouco as mãos.', 'proprio', null, 'proprio', null),
    ('mergulho_paralelas', 'Mergulho nas paralelas', 'mergulho', 'peito', array['triceps', 'ombro_anterior']::text[], 'peso_corporal', null, null, null, 'empurrar_vertical', 'peso_corporal', 'Apoiado nas paralelas com os braços estendidos, incline levemente o tronco à frente. Desça dobrando os cotovelos até o ombro ficar na altura do cotovelo e empurre de volta. Descer demais sobrecarrega a frente do ombro.', 'proprio', null, 'proprio', null),
    ('mergulho_assistido_maquina', 'Mergulho assistido na máquina', 'mergulho', 'peito', array['triceps', 'ombro_anterior']::text[], 'maquina', null, null, null, 'empurrar_vertical', 'assistencia', 'Ajoelhado ou em pé na plataforma da máquina de assistência, segure as barras paralelas. Desça dobrando os cotovelos e empurre de volta. A carga escolhida ajuda o movimento, então menos carga significa exercício mais difícil.', 'proprio', null, 'proprio', null),
    ('mergulho_maquina', 'Mergulho na máquina', 'mergulho', 'triceps', array['peito', 'ombro_anterior']::text[], 'maquina', null, null, null, 'extensao_cotovelo', 'total', 'Sentado na máquina de mergulho, segure as pegadas ao lado do corpo. Empurre para baixo até estender os cotovelos e volte devagar. Mantenha os ombros baixos, longe das orelhas.', 'proprio', null, 'proprio', null),
    ('mergulho_banco', 'Mergulho no banco', 'mergulho', 'triceps', array['peito', 'ombro_anterior']::text[], 'peso_corporal', null, null, null, 'extensao_cotovelo', 'peso_corporal', 'De costas para um banco, mãos apoiadas na borda e pernas à frente. Desça dobrando os cotovelos para trás até cerca de 90 graus e empurre de volta. Mantenha o quadril perto do banco para não forçar a frente do ombro.', 'proprio', null, 'proprio', null),
    ('pullover_halter', 'Pullover com halter', 'pullover', 'costas', array['peito', 'triceps']::text[], 'halteres', null, null, null, 'puxar_vertical', 'total', 'Deitado no banco, segure um halter com as duas mãos acima do peito, cotovelos levemente dobrados. Leve o halter para trás da cabeça em arco até alongar e volte à posição inicial. Não dobre e estique os cotovelos, o movimento é só no ombro.', 'proprio', null, 'proprio', null),
    ('pullover_polia', 'Pullover na polia', 'pullover', 'costas', array['triceps']::text[], 'cabo', null, null, null, 'puxar_vertical', 'total', 'Em pé de frente para a polia alta, segure a barra ou a corda com os braços estendidos e o tronco levemente inclinado. Puxe em arco até as mãos chegarem perto das coxas e volte controlando. Mantenha os cotovelos fixos, sem transformar em tríceps.', 'proprio', null, 'proprio', null),
    ('puxada_frontal_aberta', 'Puxada frontal aberta', 'puxada', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', 'pronada', 'aberta', 'barra_reta', 'puxar_vertical', 'total', 'Sentado com as coxas presas no apoio, segure a barra com pegada pronada mais larga que os ombros. Puxe a barra até a parte alta do peito levando os cotovelos para baixo e para trás, e volte até estender os braços. Evite jogar o tronco para trás para ganhar impulso.', 'proprio', null, 'proprio', null),
    ('puxada_frontal_supinada', 'Puxada frontal supinada', 'puxada', 'costas', array['biceps']::text[], 'cabo', 'supinada', null, 'barra_reta', 'puxar_vertical', 'total', 'Sentado com as coxas presas, segure a barra com as palmas voltadas para você, na largura dos ombros. Puxe até a parte alta do peito com os cotovelos junto ao corpo e volte estendendo os braços. Não balance o tronco.', 'proprio', null, 'proprio', null),
    ('puxada_triangulo', 'Puxada com triângulo', 'puxada', 'costas', array['biceps']::text[], 'cabo', 'neutra', 'fechada', 'triangulo', 'puxar_vertical', 'total', 'Sentado na puxada com o triângulo preso ao cabo, pegada neutra e fechada. Puxe até o peito levando os cotovelos para baixo junto ao tronco e volte devagar. Mantenha o peito aberto e evite curvar os ombros para frente.', 'proprio', null, 'proprio', null),
    ('puxada_neutra_aberta', 'Puxada neutra aberta', 'puxada', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', 'neutra', 'aberta', 'barra_neutra', 'puxar_vertical', 'total', 'Sentado na puxada com a barra de pegada neutra larga, palmas voltadas uma para a outra. Puxe até a parte alta do peito e volte até estender os braços. Leve os cotovelos para baixo, não para trás.', 'proprio', null, 'proprio', null),
    ('puxada_nuca', 'Puxada atrás da nuca', 'puxada_nuca', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', 'pronada', 'aberta', 'barra_reta', 'puxar_vertical', 'total', 'Sentado com as coxas presas, pegada pronada larga. Puxe a barra até a nuca inclinando levemente a cabeça à frente e volte estendendo os braços. Só faça se o ombro tiver mobilidade para isso sem dor.', 'proprio', null, 'proprio', null),
    ('puxada_unilateral_polia', 'Puxada unilateral na polia', 'puxada', 'costas', array['biceps']::text[], 'cabo', null, null, 'alca', 'puxar_vertical', 'total', 'Sentado ou ajoelhado sob a polia alta, segure a alça com uma mão. Puxe levando o cotovelo para baixo junto ao corpo e volte até alongar o lado das costas. Evite girar o tronco para completar o movimento.', 'proprio', null, 'proprio', null),
    ('puxada_maquina', 'Puxada na máquina articulada', 'puxada', 'costas', array['biceps']::text[], 'maquina', null, null, null, 'puxar_vertical', 'total', 'Sentado na máquina com as coxas presas, segure as pegadas acima da cabeça. Puxe para baixo levando os cotovelos ao lado do corpo e volte controlando. A máquina guia o caminho, então foque em descer os ombros antes de dobrar os cotovelos.', 'proprio', null, 'proprio', null),
    ('barra_fixa_pronada', 'Barra fixa pronada', 'barra_fixa', 'costas', array['biceps', 'ombro_posterior']::text[], 'peso_corporal', 'pronada', null, null, 'puxar_vertical', 'peso_corporal', 'Pendurado na barra com pegada pronada um pouco além da largura dos ombros. Puxe o corpo até o queixo passar a barra e desça até estender os braços. Evite balançar as pernas e encurtar a descida.', 'proprio', null, 'proprio', null),
    ('barra_fixa_supinada', 'Barra fixa supinada', 'barra_fixa', 'costas', array['biceps']::text[], 'peso_corporal', 'supinada', null, null, 'puxar_vertical', 'peso_corporal', 'Pendurado na barra com as palmas voltadas para você, na largura dos ombros. Puxe até o queixo passar a barra e desça controlando até estender os braços. Exige mais do bíceps que a versão pronada.', 'proprio', null, 'proprio', null),
    ('barra_fixa_neutra', 'Barra fixa neutra', 'barra_fixa', 'costas', array['biceps']::text[], 'peso_corporal', 'neutra', null, null, 'puxar_vertical', 'peso_corporal', 'Pendurado nas pegadas paralelas com as palmas voltadas uma para a outra. Puxe até o queixo passar as pegadas e desça até estender os braços. Costuma ser a variação mais confortável para o ombro.', 'proprio', null, 'proprio', null),
    ('barra_fixa_assistida_maquina', 'Barra fixa assistida pronada na máquina', 'barra_fixa', 'costas', array['biceps']::text[], 'maquina', 'pronada', null, null, 'puxar_vertical', 'assistencia', 'Ajoelhado ou em pé na plataforma da máquina, segure a barra e puxe até o queixo passar a pegada. Desça controlando até estender os braços. A carga ajuda a subir, então progresso é conseguir usar menos carga.', 'proprio', null, 'proprio', null),
    ('barra_fixa_assistida_elastico', 'Barra fixa assistida com elástico', 'barra_fixa', 'costas', array['biceps']::text[], 'elastico', null, null, null, 'puxar_vertical', 'peso_corporal', 'Prenda o elástico na barra e apoie o pé ou o joelho nele. Puxe até o queixo passar a barra e desça controlando. Troque por elásticos mais leves conforme ganhar força.', 'proprio', null, 'proprio', null),
    ('barra_fixa_negativa', 'Barra fixa negativa', 'barra_fixa', 'costas', array['biceps']::text[], 'peso_corporal', null, null, null, 'puxar_vertical', 'peso_corporal', 'Suba até a posição final da barra fixa com ajuda de um banco ou pulo. Desça o mais devagar que conseguir até estender totalmente os braços. Serve para quem ainda não completa a barra fixa inteira.', 'proprio', null, 'proprio', null),
    ('dead_hang', 'Suspensão na barra (dead hang)', 'suspensao', 'antebraco', array['costas', 'ombro_posterior']::text[], 'peso_corporal', null, null, null, 'pegada', 'peso_corporal', 'Pendure-se na barra com pegada pronada e os pés fora do chão. Mantenha a posição pelo tempo prescrito, com os ombros levemente puxados para baixo na versão ativa. Solte antes de a pegada falhar de vez para não cair desequilibrado.', 'proprio', null, 'proprio', null),
    ('remada_curvada_barra', 'Remada curvada pronada com barra', 'remada_curvada', 'costas', array['ombro_posterior', 'biceps', 'lombar']::text[], 'barra', 'pronada', null, null, 'puxar_horizontal', 'total', 'Em pé com os joelhos levemente dobrados, incline o tronco à frente com a coluna neutra e segure a barra com pegada pronada. Puxe a barra até o umbigo levando os cotovelos para trás e desça controlando. Erros comuns: arredondar a lombar e levantar o tronco a cada repetição.', 'proprio', null, 'proprio', null),
    ('remada_curvada_supinada', 'Remada curvada supinada com barra', 'remada_curvada', 'costas', array['biceps', 'lombar']::text[], 'barra', 'supinada', null, null, 'puxar_horizontal', 'total', 'Na mesma posição da remada curvada, segure a barra com as palmas voltadas para frente. Puxe até a parte baixa do abdômen com os cotovelos junto ao corpo e desça controlando. Mantenha o tronco parado durante a série.', 'proprio', null, 'proprio', null),
    ('remada_pendlay', 'Remada Pendlay', 'remada_pendlay', 'costas', array['ombro_posterior', 'biceps', 'lombar']::text[], 'barra', 'pronada', null, null, 'puxar_horizontal', 'total', 'Com o tronco quase paralelo ao chão e a barra apoiada no chão, puxe-a de forma explosiva até a parte baixa do peito. Devolva a barra ao chão a cada repetição. Diferente da remada curvada, cada repetição começa parada no chão.', 'proprio', null, 'proprio', null),
    ('remada_curvada_halteres', 'Remada curvada com halteres', 'remada_curvada', 'costas', array['ombro_posterior', 'biceps', 'lombar']::text[], 'halteres', null, null, null, 'puxar_horizontal', 'por_halter', 'Em pé com o tronco inclinado à frente e a coluna neutra, um halter em cada mão. Puxe os halteres ao lado do quadril levando os cotovelos para trás e desça controlando. Não use o tronco para dar impulso.', 'proprio', null, 'proprio', null),
    ('remada_unilateral_halter', 'Remada unilateral com halter (serrote)', 'remada_unilateral', 'costas', array['ombro_posterior', 'biceps']::text[], 'halteres', null, null, null, 'puxar_horizontal', 'por_halter', 'Apoie um joelho e a mão do mesmo lado no banco, tronco paralelo ao chão, halter na outra mão. Puxe o halter em direção ao quadril e desça até alongar as costas. Evite girar o tronco para subir o halter.', 'proprio', null, 'proprio', null),
    ('remada_baixa_triangulo', 'Remada baixa com triângulo', 'remada_baixa', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', 'neutra', 'fechada', 'triangulo', 'puxar_horizontal', 'total', 'Sentado na remada baixa com os pés apoiados e os joelhos levemente dobrados, segure o triângulo. Puxe até o abdômen levando os cotovelos para trás e abrindo o peito, e volte até alongar as costas. Não balance o tronco para frente e para trás.', 'proprio', null, 'proprio', null),
    ('remada_baixa_aberta', 'Remada baixa com pegada aberta', 'remada_baixa', 'costas', array['ombro_posterior', 'biceps', 'trapezio']::text[], 'cabo', 'pronada', 'aberta', 'barra_reta', 'puxar_horizontal', 'total', 'Sentado na remada baixa com uma barra reta presa ao cabo, pegada pronada larga. Puxe até a linha do peito com os cotovelos abertos e volte controlando. Mais trabalho para a parte alta das costas e posterior de ombro.', 'proprio', null, 'proprio', null),
    ('remada_maquina', 'Remada sentada na máquina', 'remada_maquina', 'costas', array['biceps', 'ombro_posterior']::text[], 'maquina', null, null, null, 'puxar_horizontal', 'total', 'Sentado na máquina com o peito no apoio, segure as pegadas. Puxe levando os cotovelos para trás e juntando as escápulas, e volte devagar. Mantenha o peito encostado no apoio durante toda a série.', 'proprio', null, 'proprio', null),
    ('remada_maquina_unilateral', 'Remada unilateral na máquina', 'remada_maquina', 'costas', array['biceps', 'ombro_posterior']::text[], 'maquina', null, null, null, 'puxar_horizontal', 'total', 'Sentado na máquina com o peito no apoio, segure uma pegada só. Puxe o cotovelo para trás até o fim do movimento e volte alongando. Evite girar o tronco para o lado que puxa.', 'proprio', null, 'proprio', null),
    ('remada_apoiada_halteres', 'Remada apoiada com halteres', 'remada_apoiada', 'costas', array['ombro_posterior', 'biceps']::text[], 'halteres', null, null, null, 'puxar_horizontal', 'por_halter', 'Deitado de bruços num banco inclinado, um halter em cada mão com os braços estendidos. Puxe os halteres levando os cotovelos para trás e desça controlando. O apoio do peito tira a lombar do movimento.', 'proprio', null, 'proprio', null),
    ('remada_apoiada_maquina', 'Remada com peito apoiado na máquina', 'remada_apoiada', 'costas', array['ombro_posterior', 'biceps']::text[], 'maquina', null, null, null, 'puxar_horizontal', 'total', 'Na máquina de remada com apoio de peito em pé ou inclinado, segure as pegadas. Puxe até os cotovelos passarem a linha do tronco e volte devagar. Não tire o peito do apoio para ganhar amplitude.', 'proprio', null, 'proprio', null),
    ('remada_cavalinho', 'Remada cavalinho', 'remada_curvada', 'costas', array['ombro_posterior', 'biceps', 'lombar']::text[], 'barra', 'neutra', 'fechada', null, 'puxar_horizontal', 'total', 'Com uma ponta da barra presa no chão ou no aparelho e a pegada perto das anilhas, incline o tronco à frente com a coluna neutra. Puxe até o peito e desça controlando. Mantenha os joelhos dobrados e a lombar firme.', 'proprio', null, 'proprio', null),
    ('remada_invertida', 'Remada invertida', 'remada_invertida', 'costas', array['biceps', 'ombro_posterior']::text[], 'peso_corporal', null, null, null, 'puxar_horizontal', 'peso_corporal', 'Deitado sob uma barra baixa, segure-a e mantenha o corpo reto com os calcanhares no chão. Puxe o peito até a barra e desça estendendo os braços. Quanto mais horizontal o corpo, mais difícil.', 'proprio', null, 'proprio', null),
    ('levantamento_terra_barra', 'Levantamento terra', 'levantamento_terra', 'gluteos', array['posterior_coxa', 'lombar', 'quadriceps', 'costas', 'trapezio', 'antebraco']::text[], 'barra', null, null, null, 'dobradica_quadril', 'total', 'Com a barra sobre o meio do pé, segure-a na largura dos ombros, quadril acima dos joelhos e coluna neutra. Empurre o chão e estenda quadril e joelhos juntos, levando a barra rente às pernas até ficar em pé. Erro mais comum: arredondar a lombar na saída do chão.', 'proprio', null, 'proprio', null),
    ('levantamento_terra_sumo', 'Levantamento terra sumô', 'levantamento_terra', 'gluteos', array['adutores', 'quadriceps', 'posterior_coxa', 'lombar']::text[], 'barra', null, null, null, 'dobradica_quadril', 'total', 'Com os pés bem afastados e as pontas para fora, segure a barra por dentro das pernas. Empurre o chão afastando os joelhos e suba até ficar em pé. Tronco mais vertical que no terra convencional.', 'proprio', null, 'proprio', null),
    ('levantamento_terra_hexagonal', 'Levantamento terra com barra hexagonal', 'levantamento_terra', 'quadriceps', array['gluteos', 'posterior_coxa', 'lombar', 'trapezio']::text[], 'barra', null, null, null, 'dobradica_quadril', 'total', 'Dentro da barra hexagonal, segure as pegadas laterais com a coluna neutra. Empurre o chão e suba até ficar em pé. O peso fica alinhado ao corpo, o que reduz a carga na lombar.', 'proprio', null, 'proprio', null),
    ('levantamento_terra_kettlebell', 'Levantamento terra com kettlebell', 'levantamento_terra', 'gluteos', array['posterior_coxa', 'quadriceps', 'lombar']::text[], 'kettlebell', null, null, null, 'dobradica_quadril', 'total', 'Em pé com o kettlebell entre os pés, empurre o quadril para trás e segure a alça com as duas mãos, coluna neutra. Suba estendendo quadril e joelhos e desça pelo mesmo caminho. Bom para aprender o padrão do terra.', 'proprio', null, 'proprio', null),
    ('extensao_lombar_45', 'Extensão lombar no banco 45°', 'extensao_lombar', 'lombar', array['gluteos', 'posterior_coxa']::text[], 'peso_corporal', null, null, null, 'dobradica_quadril', 'peso_corporal', 'No banco 45 graus com os pés presos e o quadril logo acima do apoio, desça o tronco à frente. Suba até o corpo ficar alinhado, sem passar dessa linha. Hiperestender no topo comprime a lombar.', 'proprio', null, 'proprio', null),
    ('bom_dia_barra', 'Bom dia com barra', 'bom_dia', 'posterior_coxa', array['lombar', 'gluteos']::text[], 'barra', null, null, null, 'dobradica_quadril', 'total', 'Com a barra nas costas e os joelhos levemente dobrados, empurre o quadril para trás inclinando o tronco à frente com a coluna neutra. Volte estendendo o quadril. Use carga leve até dominar o movimento.', 'proprio', null, 'proprio', null),
    ('encolhimento_halteres', 'Encolhimento com halteres', 'encolhimento', 'trapezio', array['antebraco']::text[], 'halteres', null, null, null, 'elevacao_escapula', 'por_halter', 'Em pé com um halter em cada mão ao lado do corpo. Eleve os ombros em direção às orelhas, segure um instante e desça devagar. Não gire os ombros nem dobre os cotovelos.', 'proprio', null, 'proprio', null),
    ('encolhimento_barra', 'Encolhimento com barra', 'encolhimento', 'trapezio', array['antebraco']::text[], 'barra', null, null, null, 'elevacao_escapula', 'total', 'Em pé segurando a barra à frente das coxas com pegada pronada. Eleve os ombros o máximo que conseguir e desça controlando. Mantenha os braços estendidos durante todo o movimento.', 'proprio', null, 'proprio', null),
    ('encolhimento_maquina', 'Encolhimento na máquina', 'encolhimento', 'trapezio', array['antebraco']::text[], 'maquina', null, null, null, 'elevacao_escapula', 'total', 'Na máquina de encolhimento ou no smith, segure as pegadas com os braços estendidos. Eleve os ombros e desça devagar. Ajuste a altura para começar com os ombros bem baixos.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_militar_barra', 'Desenvolvimento militar com barra', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'barra', null, null, null, 'empurrar_vertical', 'total', 'Em pé com a barra apoiada na frente dos ombros, pegada pouco além da largura deles e abdômen firme. Empurre a barra acima da cabeça até estender os cotovelos, passando a cabeça para frente no topo, e desça até a clavícula. Evite arquear a lombar para ajudar.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_barra_sentado', 'Desenvolvimento com barra sentado', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'barra', null, null, null, 'empurrar_vertical', 'total', 'Sentado no banco com encosto vertical, barra apoiada à frente dos ombros. Empurre acima da cabeça e desça até a altura do queixo. O encosto tira o quadril e as pernas do movimento.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_halteres', 'Desenvolvimento com halteres', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'halteres', null, null, null, 'empurrar_vertical', 'por_halter', 'Sentado no banco com encosto vertical, halteres na altura das orelhas com os cotovelos levemente à frente do corpo. Empurre para cima até quase encostar os halteres e desça até a altura das orelhas. Vale também fazendo alternado.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_halteres_em_pe', 'Desenvolvimento com halteres em pé', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps', 'abdomen']::text[], 'halteres', null, null, null, 'empurrar_vertical', 'por_halter', 'Em pé com os halteres na altura dos ombros e o abdômen firme. Empurre para cima até estender os cotovelos e desça controlando. Sem o encosto, o tronco precisa ficar estável por conta própria, então evite inclinar para trás.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_unilateral_ajoelhado', 'Desenvolvimento unilateral com halter meio ajoelhado', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps', 'abdomen']::text[], 'halteres', null, null, null, 'empurrar_vertical', 'por_halter', 'Com um joelho no chão e o outro pé à frente, segure um halter na altura do ombro do lado do joelho apoiado. Empurre acima da cabeça sem inclinar o tronco e desça controlando. Contraia o glúteo da perna de trás para estabilizar.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_arnold', 'Desenvolvimento Arnold', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'halteres', null, null, null, 'empurrar_vertical', 'por_halter', 'Sentado, comece com os halteres à frente do rosto e as palmas voltadas para você. Ao empurrar, gire as palmas para frente até estender os braços acima da cabeça, e faça o caminho inverso na descida. Use carga menor que no desenvolvimento comum.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_maquina', 'Desenvolvimento na máquina', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'maquina', null, null, null, 'empurrar_vertical', 'total', 'Sentado na máquina com as costas apoiadas, ajuste o banco para as pegadas ficarem na altura dos ombros. Empurre para cima e desça controlando. Não tire as costas do encosto.', 'proprio', null, 'proprio', null),
    ('desenvolvimento_smith', 'Desenvolvimento no smith', 'desenvolvimento', 'ombro_anterior', array['ombro_lateral', 'triceps']::text[], 'maquina', null, null, null, 'empurrar_vertical', 'total', 'Sentado no banco com encosto sob a barra guiada, ajuste para a barra descer à frente do rosto. Empurre até estender os cotovelos e desça até a altura do queixo. Confira a trava antes de soltar a barra.', 'proprio', null, 'proprio', null),
    ('elevacao_lateral_halteres', 'Elevação lateral com halteres', 'elevacao_lateral', 'ombro_lateral', array['trapezio']::text[], 'halteres', null, null, null, 'elevacao_ombro', 'por_halter', 'Em pé ou sentado, halteres ao lado do corpo e cotovelos levemente dobrados. Eleve os braços para os lados até a altura dos ombros e desça devagar. Evite balançar o tronco e subir os ombros junto.', 'proprio', null, 'proprio', null),
    ('elevacao_lateral_polia', 'Elevação lateral na polia', 'elevacao_lateral', 'ombro_lateral', array['trapezio']::text[], 'cabo', null, null, 'alca', 'elevacao_ombro', 'total', 'De lado para a polia baixa, segure a alça com a mão do lado oposto. Eleve o braço para o lado até a altura do ombro e desça controlando. O cabo mantém tensão também no início do movimento, onde o halter pesa pouco.', 'proprio', null, 'proprio', null),
    ('elevacao_lateral_maquina', 'Elevação lateral na máquina', 'elevacao_lateral', 'ombro_lateral', array['trapezio']::text[], 'maquina', null, null, null, 'elevacao_ombro', 'total', 'Sentado na máquina com os braços apoiados nas almofadas, eleve os cotovelos para os lados até a altura dos ombros. Desça devagar sem soltar o peso. Ajuste o banco para o ombro ficar alinhado ao eixo da máquina.', 'proprio', null, 'proprio', null),
    ('elevacao_frontal_halteres', 'Elevação frontal com halteres', 'elevacao_frontal', 'ombro_anterior', array['ombro_lateral']::text[], 'halteres', null, null, null, 'elevacao_ombro', 'por_halter', 'Em pé com os halteres à frente das coxas, eleve os braços à frente até a altura dos ombros e desça devagar. Pode ser simultâneo ou alternado. Não jogue o tronco para trás para subir o peso.', 'proprio', null, 'proprio', null),
    ('elevacao_frontal_anilha', 'Elevação frontal com anilha', 'elevacao_frontal', 'ombro_anterior', array['ombro_lateral']::text[], 'outro', null, null, null, 'elevacao_ombro', 'total', 'Em pé segurando uma anilha com as duas mãos à frente das coxas. Eleve a anilha à frente até a altura dos olhos e desça devagar. Mantenha os cotovelos levemente dobrados e fixos.', 'proprio', null, 'proprio', null),
    ('elevacao_frontal_barra', 'Elevação frontal com barra', 'elevacao_frontal', 'ombro_anterior', array['ombro_lateral']::text[], 'barra', null, null, null, 'elevacao_ombro', 'total', 'Em pé segurando a barra com pegada pronada na largura dos ombros. Eleve à frente até a altura dos ombros e desça controlando. Evite usar impulso do quadril.', 'proprio', null, 'proprio', null),
    ('elevacao_frontal_polia', 'Elevação frontal na polia', 'elevacao_frontal', 'ombro_anterior', array['ombro_lateral']::text[], 'cabo', null, null, null, 'elevacao_ombro', 'total', 'De costas para a polia baixa, segure a barra ou a corda entre as pernas. Eleve à frente até a altura dos ombros e desça devagar. O cabo mantém tensão contínua durante todo o arco.', 'proprio', null, 'proprio', null),
    ('crucifixo_invertido_halteres', 'Crucifixo invertido com halteres', 'crucifixo_invertido', 'ombro_posterior', array['trapezio', 'costas']::text[], 'halteres', null, null, null, 'puxar_horizontal', 'por_halter', 'Com o tronco inclinado à frente e a coluna neutra, halteres pendurados sob o peito. Abra os braços para os lados até a linha dos ombros, cotovelos levemente dobrados, e desça devagar. Não junte as escápulas no fim, o foco é a parte de trás do ombro.', 'proprio', null, 'proprio', null),
    ('crucifixo_invertido_maquina', 'Crucifixo invertido na máquina', 'crucifixo_invertido', 'ombro_posterior', array['trapezio', 'costas']::text[], 'maquina', null, null, null, 'puxar_horizontal', 'total', 'Sentado de frente para o encosto do peck deck, segure as pegadas com os braços estendidos à frente. Abra os braços para trás até a linha do corpo e volte devagar. Mantenha o peito encostado.', 'proprio', null, 'proprio', null),
    ('crucifixo_invertido_polia', 'Crucifixo invertido na polia', 'crucifixo_invertido', 'ombro_posterior', array['trapezio', 'costas']::text[], 'cabo', null, null, null, 'puxar_horizontal', 'total', 'Entre as polias na altura dos ombros, segure o cabo da esquerda com a mão direita e o da direita com a esquerda. Abra os braços para trás até a linha do corpo e volte controlando. Mantenha os cotovelos levemente dobrados e fixos.', 'proprio', null, 'proprio', null),
    ('face_pull', 'Face pull na polia', 'face_pull', 'ombro_posterior', array['trapezio', 'costas']::text[], 'cabo', null, null, 'corda', 'puxar_horizontal', 'total', 'Com a corda presa na polia alta, segure as pontas com as palmas para baixo. Puxe em direção ao rosto separando as mãos e levando os cotovelos para fora e para trás, e volte controlando. Evite puxar só com o bíceps.', 'proprio', null, 'proprio', null),
    ('remada_alta_barra', 'Remada alta com barra', 'remada_alta', 'ombro_lateral', array['trapezio', 'biceps']::text[], 'barra', 'pronada', null, null, 'elevacao_ombro', 'total', 'Em pé segurando a barra à frente das coxas com pegada pronada na largura dos ombros. Puxe a barra junto ao corpo até a parte baixa do peito com os cotovelos acima das mãos e desça devagar. Subir acima do peito costuma incomodar o ombro.', 'proprio', null, 'proprio', null),
    ('remada_alta_polia', 'Remada alta na polia', 'remada_alta', 'ombro_lateral', array['trapezio', 'biceps']::text[], 'cabo', null, null, null, 'elevacao_ombro', 'total', 'De frente para a polia baixa com a barra presa, puxe a barra junto ao corpo até a parte baixa do peito, cotovelos acima das mãos. Desça controlando. Mantenha o tronco parado.', 'proprio', null, 'proprio', null),
    ('rotacao_externa_polia', 'Rotação externa de ombro na polia', 'rotacao_ombro', 'ombro_posterior', '{}'::text[], 'cabo', null, null, null, 'rotacao_ombro', 'total', 'De lado para a polia na altura do cotovelo, cotovelo dobrado a 90 graus e colado ao corpo, segure a alça com a mão de fora. Gire o antebraço para fora sem afastar o cotovelo do corpo e volte devagar. Use carga leve.', 'proprio', null, 'proprio', null),
    ('rosca_direta_barra', 'Rosca direta com barra', 'rosca_direta', 'biceps', array['antebraco']::text[], 'barra', 'supinada', null, 'barra_reta', 'flexao_cotovelo', 'total', 'Em pé segurando a barra reta com as palmas para frente, na largura dos ombros, cotovelos junto ao corpo. Suba a barra dobrando os cotovelos e desça até estender os braços. Erro comum: balançar o tronco e levar os cotovelos para frente.', 'proprio', null, 'proprio', null),
    ('rosca_direta_barra_w', 'Rosca direta com barra W', 'rosca_direta', 'biceps', array['antebraco']::text[], 'barra', 'supinada', null, 'barra_w', 'flexao_cotovelo', 'total', 'Em pé segurando a barra W nas curvas internas ou externas, cotovelos junto ao corpo. Suba a barra dobrando os cotovelos e desça até estender. A curva da barra alivia o punho em relação à barra reta.', 'proprio', null, 'proprio', null),
    ('rosca_direta_halteres', 'Rosca direta com halteres', 'rosca_direta', 'biceps', array['antebraco']::text[], 'halteres', 'supinada', null, null, 'flexao_cotovelo', 'por_halter', 'Em pé ou sentado com um halter em cada mão, palmas para frente e cotovelos junto ao corpo. Suba os halteres dobrando os cotovelos e desça até estender, juntos ou alternando os braços. Evite girar o ombro para frente no topo.', 'proprio', null, 'proprio', null),
    ('rosca_martelo_halteres', 'Rosca martelo com halteres', 'rosca_martelo', 'biceps', array['antebraco']::text[], 'halteres', 'neutra', null, null, 'flexao_cotovelo', 'por_halter', 'Em pé com os halteres ao lado do corpo e as palmas voltadas uma para a outra. Suba dobrando os cotovelos sem girar o punho e desça devagar. Pode alternar os braços.', 'proprio', null, 'proprio', null),
    ('rosca_martelo_polia_corda', 'Rosca martelo na polia com corda', 'rosca_martelo', 'biceps', array['antebraco']::text[], 'cabo', 'neutra', null, 'corda', 'flexao_cotovelo', 'total', 'De frente para a polia baixa com a corda presa, segure as pontas com as palmas voltadas uma para a outra. Suba dobrando os cotovelos junto ao corpo e desça controlando. O cabo mantém tensão no começo do movimento.', 'proprio', null, 'proprio', null),
    ('rosca_scott_barra', 'Rosca Scott com barra W', 'rosca_scott', 'biceps', array['antebraco']::text[], 'barra', 'supinada', null, 'barra_w', 'flexao_cotovelo', 'total', 'Sentado no banco Scott com a parte de trás dos braços apoiada, segure a barra W com as palmas para cima. Suba dobrando os cotovelos e desça até quase estender, sem travar embaixo. Não tire os braços do apoio.', 'proprio', null, 'proprio', null),
    ('rosca_scott_halter', 'Rosca Scott unilateral com halter', 'rosca_scott', 'biceps', array['antebraco']::text[], 'halteres', null, null, null, 'flexao_cotovelo', 'por_halter', 'No banco Scott com um braço apoiado, segure o halter com a palma para cima. Suba dobrando o cotovelo e desça controlando até quase estender. Faça a série inteira de um lado e depois do outro.', 'proprio', null, 'proprio', null),
    ('rosca_scott_maquina', 'Rosca Scott na máquina', 'rosca_scott', 'biceps', array['antebraco']::text[], 'maquina', null, null, null, 'flexao_cotovelo', 'total', 'Sentado na máquina com os braços no apoio e o cotovelo alinhado ao eixo, segure as pegadas. Suba dobrando os cotovelos e desça devagar. Ajuste o banco para o ombro não subir durante o movimento.', 'proprio', null, 'proprio', null),
    ('rosca_concentrada', 'Rosca concentrada', 'rosca_concentrada', 'biceps', array['antebraco']::text[], 'halteres', null, null, null, 'flexao_cotovelo', 'por_halter', 'Sentado com o cotovelo apoiado na parte interna da coxa, halter na mão com o braço estendido. Suba dobrando o cotovelo e desça devagar. O apoio impede que o ombro ajude.', 'proprio', null, 'proprio', null),
    ('rosca_inclinada_halteres', 'Rosca no banco inclinado com halteres', 'rosca_direta', 'biceps', array['antebraco']::text[], 'halteres', null, null, null, 'flexao_cotovelo', 'por_halter', 'Sentado num banco inclinado a cerca de 45 graus, braços pendurados ao lado do corpo com os halteres. Suba dobrando os cotovelos sem trazê-los para frente e desça até estender. A posição alonga mais o bíceps no início.', 'proprio', null, 'proprio', null),
    ('rosca_direta_polia', 'Rosca direta na polia', 'rosca_direta', 'biceps', array['antebraco']::text[], 'cabo', 'supinada', null, 'barra_reta', 'flexao_cotovelo', 'total', 'De frente para a polia baixa com a barra presa, palmas para cima e cotovelos junto ao corpo. Suba dobrando os cotovelos e desça até estender. Não dê passo para trás durante a série.', 'proprio', null, 'proprio', null),
    ('rosca_inversa_barra', 'Rosca inversa com barra', 'rosca_inversa', 'antebraco', array['biceps']::text[], 'barra', 'pronada', null, 'barra_reta', 'flexao_cotovelo', 'total', 'Em pé segurando a barra com pegada pronada, palmas para baixo, na largura dos ombros. Suba dobrando os cotovelos sem deixar o punho cair e desça devagar. Carga menor que na rosca direta.', 'proprio', null, 'proprio', null),
    ('rosca_inversa_polia', 'Rosca inversa na polia', 'rosca_inversa', 'antebraco', array['biceps']::text[], 'cabo', 'pronada', null, 'barra_reta', 'flexao_cotovelo', 'total', 'De frente para a polia baixa, segure a barra com as palmas para baixo. Suba dobrando os cotovelos junto ao corpo e desça controlando. Mantenha o punho alinhado ao antebraço.', 'proprio', null, 'proprio', null),
    ('triceps_polia_barra', 'Tríceps na polia com barra reta', 'triceps_polia', 'triceps', '{}'::text[], 'cabo', 'pronada', null, 'barra_reta', 'extensao_cotovelo', 'total', 'De frente para a polia alta, segure a barra com pegada pronada e os cotovelos colados ao corpo. Empurre a barra para baixo até estender os cotovelos e volte até cerca de 90 graus. Evite afastar os cotovelos e inclinar o tronco sobre a barra.', 'proprio', null, 'proprio', null),
    ('triceps_polia_barra_w', 'Tríceps na polia com barra W', 'triceps_polia', 'triceps', '{}'::text[], 'cabo', 'pronada', null, 'barra_w', 'extensao_cotovelo', 'total', 'De frente para a polia alta com a barra W presa, cotovelos colados ao corpo. Empurre para baixo até estender e volte devagar. A curva da barra deixa o punho numa posição mais natural.', 'proprio', null, 'proprio', null),
    ('triceps_polia_corda', 'Tríceps na polia com corda', 'triceps_polia', 'triceps', '{}'::text[], 'cabo', 'neutra', null, 'corda', 'extensao_cotovelo', 'total', 'De frente para a polia alta com a corda presa, cotovelos colados ao corpo. Empurre para baixo separando as pontas da corda no fim e volte devagar até cerca de 90 graus. Não deixe os cotovelos subirem na volta.', 'proprio', null, 'proprio', null),
    ('triceps_polia_unilateral', 'Tríceps unilateral na polia', 'triceps_polia', 'triceps', '{}'::text[], 'cabo', null, null, 'alca', 'extensao_cotovelo', 'total', 'De frente para a polia alta, segure a alça com uma mão e o cotovelo colado ao corpo. Empurre para baixo até estender e volte controlando. Faça a série inteira de um lado antes de trocar.', 'proprio', null, 'proprio', null),
    ('triceps_testa_barra', 'Tríceps testa com barra W', 'triceps_testa', 'triceps', '{}'::text[], 'barra', 'pronada', null, 'barra_w', 'extensao_cotovelo', 'total', 'Deitado no banco, segure a barra W acima do peito com os braços estendidos. Dobre só os cotovelos levando a barra em direção à testa e estenda de volta. Mantenha os cotovelos apontando para o teto, sem abrir.', 'proprio', null, 'proprio', null),
    ('triceps_testa_halteres', 'Tríceps testa com halteres', 'triceps_testa', 'triceps', '{}'::text[], 'halteres', null, null, null, 'extensao_cotovelo', 'por_halter', 'Deitado no banco, um halter em cada mão acima do peito com as palmas voltadas uma para a outra. Dobre os cotovelos levando os halteres ao lado da cabeça e estenda de volta. Cotovelos fixos apontando para o teto.', 'proprio', null, 'proprio', null),
    ('triceps_testa_polia', 'Tríceps testa na polia', 'triceps_testa', 'triceps', '{}'::text[], 'cabo', null, null, null, 'extensao_cotovelo', 'total', 'Deitado no banco com a cabeça voltada para a polia baixa, segure a barra ou a corda acima do peito. Dobre os cotovelos levando as mãos em direção à testa e estenda de volta. O cabo mantém tensão no topo do movimento.', 'proprio', null, 'proprio', null),
    ('triceps_frances_halter', 'Tríceps francês com halter', 'triceps_frances', 'triceps', '{}'::text[], 'halteres', null, null, null, 'extensao_cotovelo', 'total', 'Sentado ou em pé, segure um halter com as duas mãos acima da cabeça. Desça o halter atrás da cabeça dobrando só os cotovelos e estenda de volta. Mantenha os cotovelos apontando para cima, sem abrir para os lados.', 'proprio', null, 'proprio', null),
    ('triceps_frances_unilateral', 'Tríceps francês unilateral com halter', 'triceps_frances', 'triceps', '{}'::text[], 'halteres', null, null, null, 'extensao_cotovelo', 'por_halter', 'Sentado ou em pé, segure um halter com uma mão acima da cabeça. Desça atrás da cabeça dobrando o cotovelo e estenda de volta. Use a outra mão para manter o cotovelo no lugar, se precisar.', 'proprio', null, 'proprio', null),
    ('triceps_frances_polia', 'Tríceps francês na polia', 'triceps_frances', 'triceps', '{}'::text[], 'cabo', 'neutra', null, 'corda', 'extensao_cotovelo', 'total', 'De costas para a polia com a corda presa, tronco levemente inclinado à frente e as mãos atrás da cabeça. Estenda os cotovelos levando a corda à frente e acima, e volte devagar até alongar. Cotovelos fixos ao lado da cabeça.', 'proprio', null, 'proprio', null),
    ('triceps_coice_halter', 'Tríceps coice com halter', 'triceps_coice', 'triceps', '{}'::text[], 'halteres', null, null, null, 'extensao_cotovelo', 'por_halter', 'Com o tronco inclinado à frente e o braço junto ao corpo, cotovelo dobrado a 90 graus. Estenda o cotovelo levando o halter para trás e volte devagar. O braço fica parado, só o antebraço se move.', 'proprio', null, 'proprio', null),
    ('triceps_coice_polia', 'Tríceps coice na polia', 'triceps_coice', 'triceps', '{}'::text[], 'cabo', null, null, null, 'extensao_cotovelo', 'total', 'De frente para a polia baixa, tronco inclinado à frente e o braço junto ao corpo, segure a alça sem o pegador. Estenda o cotovelo para trás e volte controlando. O cabo mantém tensão no começo, onde o halter pesa pouco.', 'proprio', null, 'proprio', null),
    ('triceps_maquina', 'Tríceps na máquina', 'triceps_maquina', 'triceps', '{}'::text[], 'maquina', null, null, null, 'extensao_cotovelo', 'total', 'Sentado na máquina de tríceps com os braços apoiados e o cotovelo alinhado ao eixo, segure as pegadas. Estenda os cotovelos e volte devagar. Ajuste o banco para os ombros não subirem.', 'proprio', null, 'proprio', null),
    ('rosca_punho_barra', 'Rosca de punho com barra', 'rosca_punho', 'antebraco', '{}'::text[], 'barra', 'supinada', null, null, 'pegada', 'total', 'Sentado com os antebraços apoiados nas coxas ou no banco, segure a barra com as palmas para cima e os punhos para fora do apoio. Flexione os punhos subindo a barra e desça devagar. Amplitude curta e controlada.', 'proprio', null, 'proprio', null),
    ('rosca_punho_inversa_barra', 'Rosca de punho inversa com barra', 'rosca_punho', 'antebraco', '{}'::text[], 'barra', 'pronada', null, null, 'pegada', 'total', 'Sentado com os antebraços apoiados, segure a barra com as palmas para baixo e os punhos para fora do apoio. Estenda os punhos subindo a barra e desça devagar. Use carga bem menor que na rosca de punho comum.', 'proprio', null, 'proprio', null),
    ('rosca_punho_halter', 'Rosca de punho com halter', 'rosca_punho', 'antebraco', '{}'::text[], 'halteres', null, null, null, 'pegada', 'por_halter', 'Sentado com o antebraço apoiado na coxa e o punho para fora, segure o halter com a palma para cima. Flexione o punho subindo o halter e desça devagar. Faça um lado de cada vez.', 'proprio', null, 'proprio', null),
    ('pinca_anilhas', 'Pinça de anilhas', 'pegada', 'antebraco', '{}'::text[], 'outro', null, null, null, 'pegada', 'total', 'Junte duas anilhas lisas com os lados lisos para fora e segure-as só com os dedos e o polegar, braço estendido ao lado do corpo. Mantenha pelo tempo prescrito. Trabalha a força de pinça dos dedos.', 'proprio', null, 'proprio', null),
    ('rolo_punho', 'Rolo de punho', 'pegada', 'antebraco', '{}'::text[], 'outro', null, null, null, 'pegada', 'total', 'Em pé com os braços estendidos à frente, segure o rolo com uma corda e uma anilha presa na ponta. Gire os punhos enrolando a corda até a anilha subir e desenrole devagar. Não deixe os ombros subirem.', 'proprio', null, 'proprio', null),
    ('agachamento_livre_barra', 'Agachamento livre com barra', 'agachamento', 'quadriceps', array['gluteos', 'adutores', 'lombar']::text[], 'barra', null, null, null, 'agachar', 'total', 'Com a barra apoiada no trapézio, pés na largura dos ombros e pontas levemente para fora. Desça dobrando quadril e joelhos ao mesmo tempo, joelhos acompanhando a direção dos pés, até a profundidade que mantiver a coluna neutra, e suba empurrando o chão. Erros comuns: joelhos fechando para dentro e calcanhar saindo do chão.', 'proprio', null, 'proprio', null),
    ('agachamento_frontal_barra', 'Agachamento frontal com barra', 'agachamento', 'quadriceps', array['gluteos', 'abdomen']::text[], 'barra', null, null, null, 'agachar', 'total', 'Com a barra apoiada na frente dos ombros e os cotovelos altos, pés na largura dos ombros. Desça mantendo o tronco o mais vertical possível e suba empurrando o chão. Se os cotovelos caírem, a barra rola para frente.', 'proprio', null, 'proprio', null),
    ('agachamento_zercher', 'Agachamento Zercher', 'agachamento', 'quadriceps', array['gluteos', 'abdomen', 'lombar']::text[], 'barra', null, null, null, 'agachar', 'total', 'Com a barra apoiada na dobra dos cotovelos, junto ao corpo, pés na largura dos ombros. Desça com o tronco ereto e suba empurrando o chão. Use um protetor na barra se a dobra do cotovelo incomodar.', 'proprio', null, 'proprio', null),
    ('agachamento_smith', 'Agachamento no smith', 'agachamento', 'quadriceps', array['gluteos', 'adutores']::text[], 'maquina', null, null, null, 'agachar', 'total', 'Com a barra guiada apoiada no trapézio e os pés um pouco à frente do corpo, destrave e desça dobrando quadril e joelhos. Suba empurrando o chão. A posição dos pés muda bastante o exercício, então mantenha a mesma entre as sessões.', 'proprio', null, 'proprio', null),
    ('agachamento_hack', 'Agachamento hack na máquina', 'agachamento', 'quadriceps', array['gluteos', 'adutores']::text[], 'maquina', null, null, null, 'agachar', 'total', 'Com as costas no encosto e os ombros sob as almofadas, pés na plataforma na largura dos ombros. Destrave, desça dobrando os joelhos até cerca de 90 graus ou mais e suba empurrando a plataforma. Mantenha a lombar encostada.', 'proprio', null, 'proprio', null),
    ('agachamento_pendulo', 'Agachamento pêndulo', 'agachamento', 'quadriceps', array['gluteos']::text[], 'maquina', null, null, null, 'agachar', 'total', 'Na máquina pêndulo com as costas no encosto e os ombros sob as almofadas, desça dobrando os joelhos e suba empurrando a plataforma. O arco da máquina mantém o tronco estável. Não tire o quadril do encosto.', 'proprio', null, 'proprio', null),
    ('agachamento_goblet_halter', 'Agachamento goblet com halter', 'agachamento', 'quadriceps', array['gluteos', 'adutores', 'abdomen']::text[], 'halteres', null, null, null, 'agachar', 'total', 'Segure um halter em pé junto ao peito, com as duas mãos sob a cabeça dele. Desça entre os joelhos com o tronco ereto e suba empurrando o chão. Os cotovelos podem tocar a parte interna dos joelhos no fundo.', 'proprio', null, 'proprio', null),
    ('agachamento_goblet_kettlebell', 'Agachamento goblet com kettlebell', 'agachamento', 'quadriceps', array['gluteos', 'adutores', 'abdomen']::text[], 'kettlebell', null, null, null, 'agachar', 'total', 'Segure o kettlebell pela alça junto ao peito. Desça entre os joelhos com o tronco ereto e suba empurrando o chão. Mantenha os cotovelos junto ao corpo.', 'proprio', null, 'proprio', null),
    ('agachamento_sumo_halter', 'Agachamento sumô com halter', 'agachamento', 'adutores', array['quadriceps', 'gluteos']::text[], 'halteres', null, null, null, 'agachar', 'total', 'Com os pés bem afastados e as pontas para fora, segure um halter pendurado entre as pernas. Desça com o tronco ereto, joelhos abrindo na direção dos pés, e suba contraindo glúteos e adutores. Não deixe os joelhos fecharem.', 'proprio', null, 'proprio', null),
    ('agachamento_peso_corporal', 'Agachamento sem carga', 'agachamento', 'quadriceps', array['gluteos']::text[], 'peso_corporal', null, null, null, 'agachar', 'peso_corporal', 'Em pé com os pés na largura dos ombros, braços à frente para equilibrar. Desça dobrando quadril e joelhos e suba empurrando o chão. Bom para aquecer e aprender o padrão do agachamento.', 'proprio', null, 'proprio', null),
    ('agachamento_bulgaro_halteres', 'Agachamento búlgaro com halteres', 'agachamento_bulgaro', 'quadriceps', array['gluteos', 'adutores']::text[], 'halteres', null, null, null, 'afundo', 'por_halter', 'De costas para um banco, apoie o peito do pé de trás nele e dê um passo à frente com a outra perna, halteres nas mãos. Desça até o joelho de trás quase tocar o chão e suba empurrando com a perna da frente. Tronco mais inclinado puxa o trabalho para o glúteo.', 'proprio', null, 'proprio', null),
    ('agachamento_bulgaro_peso_corporal', 'Agachamento búlgaro sem carga', 'agachamento_bulgaro', 'quadriceps', array['gluteos']::text[], 'peso_corporal', null, null, null, 'afundo', 'peso_corporal', 'Com o peito do pé de trás apoiado no banco e a outra perna à frente, desça até o joelho de trás quase tocar o chão. Suba empurrando com a perna da frente. Mantenha o joelho da frente alinhado com o pé.', 'proprio', null, 'proprio', null),
    ('afundo_halteres', 'Afundo com halteres', 'afundo', 'quadriceps', array['gluteos', 'adutores']::text[], 'halteres', null, null, null, 'afundo', 'por_halter', 'Com um pé à frente e o outro atrás, halteres nas mãos e tronco ereto. Desça até o joelho de trás quase tocar o chão e suba sem mexer os pés. Faça todas as repetições de uma perna e troque.', 'proprio', null, 'proprio', null),
    ('afundo_barra', 'Afundo com barra', 'afundo', 'quadriceps', array['gluteos', 'adutores']::text[], 'barra', null, null, null, 'afundo', 'total', 'Com a barra no trapézio, um pé à frente e o outro atrás. Desça até o joelho de trás quase tocar o chão e suba sem mexer os pés. Base um pouco aberta na lateral ajuda no equilíbrio.', 'proprio', null, 'proprio', null),
    ('afundo_smith', 'Afundo no smith', 'afundo', 'quadriceps', array['gluteos']::text[], 'maquina', null, null, null, 'afundo', 'total', 'Com a barra guiada no trapézio, um pé à frente e o outro atrás. Desça até o joelho de trás quase tocar o chão e suba. A barra guiada tira o equilíbrio da equação.', 'proprio', null, 'proprio', null),
    ('avanco_halteres', 'Avanço com halteres', 'afundo', 'quadriceps', array['gluteos', 'adutores']::text[], 'halteres', null, null, null, 'afundo', 'por_halter', 'Em pé com halteres nas mãos, dê um passo largo à frente e desça até o joelho de trás quase tocar o chão. Empurre com a perna da frente para voltar ou para seguir caminhando. Mantenha o tronco ereto.', 'proprio', null, 'proprio', null),
    ('afundo_reverso_halteres', 'Afundo reverso com halteres', 'afundo', 'quadriceps', array['gluteos', 'adutores']::text[], 'halteres', null, null, null, 'afundo', 'por_halter', 'Em pé com halteres nas mãos, dê um passo para trás e desça até o joelho de trás quase tocar o chão. Volte empurrando com a perna da frente. Costuma ser mais confortável para o joelho que o avanço.', 'proprio', null, 'proprio', null),
    ('subida_banco_halteres', 'Subida no banco com halteres', 'subida_banco', 'quadriceps', array['gluteos']::text[], 'halteres', null, null, null, 'afundo', 'por_halter', 'De frente para um banco ou caixote, halteres nas mãos, apoie um pé inteiro em cima. Suba empurrando com essa perna até ficar em pé no banco e desça controlando. Evite dar impulso com a perna de baixo.', 'proprio', null, 'proprio', null),
    ('leg_press_45', 'Leg press 45°', 'leg_press', 'quadriceps', array['gluteos', 'adutores']::text[], 'maquina', null, null, null, 'agachar', 'total', 'Sentado com as costas e o quadril apoiados, pés na plataforma na largura dos ombros. Destrave, desça dobrando os joelhos até onde a lombar continuar apoiada e empurre de volta sem travar os joelhos. Pés mais altos na plataforma puxam o trabalho para glúteo e posterior.', 'proprio', null, 'proprio', null),
    ('leg_press_horizontal', 'Leg press horizontal', 'leg_press', 'quadriceps', array['gluteos', 'adutores']::text[], 'maquina', null, null, null, 'agachar', 'total', 'Sentado na máquina com as costas apoiadas e os pés na plataforma à frente. Empurre a plataforma estendendo os joelhos sem travar e volte devagar. Mantenha o quadril no assento.', 'proprio', null, 'proprio', null),
    ('leg_press_unilateral', 'Leg press 45° unilateral', 'leg_press', 'quadriceps', array['gluteos']::text[], 'maquina', null, null, null, 'agachar', 'total', 'No leg press 45 graus com um pé só no meio da plataforma. Desça controlando até onde a lombar continuar apoiada e empurre de volta. Use bem menos da metade da carga do bilateral.', 'proprio', null, 'proprio', null),
    ('cadeira_extensora', 'Cadeira extensora', 'extensora', 'quadriceps', '{}'::text[], 'maquina', null, null, null, 'extensao_joelho', 'total', 'Sentado com as costas apoiadas e o rolo sobre o peito do pé, joelho alinhado ao eixo da máquina. Estenda os joelhos até quase travar e desça devagar. Segure no banco para o quadril não sair do assento.', 'proprio', null, 'proprio', null),
    ('cadeira_extensora_unilateral', 'Cadeira extensora unilateral', 'extensora', 'quadriceps', '{}'::text[], 'maquina', null, null, null, 'extensao_joelho', 'total', 'Na cadeira extensora com uma perna só sob o rolo, estenda o joelho até quase travar e desça devagar. Faça todas as repetições de um lado e troque. Ajuda a igualar força entre as pernas.', 'proprio', null, 'proprio', null),
    ('agachamento_sissy', 'Agachamento sissy', 'agachamento', 'quadriceps', '{}'::text[], 'peso_corporal', null, null, null, 'agachar', 'peso_corporal', 'Em pé segurando num apoio, suba na ponta dos pés e incline o corpo para trás enquanto os joelhos vão à frente e para baixo. Desça até onde o joelho tolerar e volte. Comece com pouca amplitude.', 'proprio', null, 'proprio', null),
    ('mesa_flexora', 'Mesa flexora', 'flexora', 'posterior_coxa', array['panturrilha']::text[], 'maquina', null, null, null, 'flexao_joelho', 'total', 'Deitado de bruços com o rolo logo acima dos calcanhares e o joelho alinhado ao eixo da máquina. Dobre os joelhos trazendo o rolo em direção ao glúteo e desça devagar. Não levante o quadril do banco.', 'proprio', null, 'proprio', null),
    ('cadeira_flexora', 'Cadeira flexora', 'flexora', 'posterior_coxa', array['panturrilha']::text[], 'maquina', null, null, null, 'flexao_joelho', 'total', 'Sentado com o rolo atrás dos calcanhares e a trava sobre as coxas, joelho alinhado ao eixo. Dobre os joelhos puxando o rolo para baixo e volte devagar. A posição sentada alonga mais o posterior.', 'proprio', null, 'proprio', null),
    ('flexora_em_pe', 'Flexora em pé unilateral', 'flexora', 'posterior_coxa', array['panturrilha']::text[], 'maquina', null, null, null, 'flexao_joelho', 'total', 'Em pé na máquina, com o rolo atrás do calcanhar de uma perna. Dobre o joelho trazendo o calcanhar ao glúteo e desça devagar. Mantenha o quadril parado.', 'proprio', null, 'proprio', null),
    ('stiff_barra', 'Stiff com barra', 'stiff', 'posterior_coxa', array['gluteos', 'lombar']::text[], 'barra', null, null, null, 'dobradica_quadril', 'total', 'Em pé segurando a barra à frente das coxas, joelhos levemente dobrados. Empurre o quadril para trás descendo a barra rente às pernas até sentir o posterior alongar, coluna neutra, e volte estendendo o quadril. Erro comum: arredondar as costas para descer mais.', 'proprio', null, 'proprio', null),
    ('stiff_halteres', 'Stiff com halteres', 'stiff', 'posterior_coxa', array['gluteos', 'lombar']::text[], 'halteres', null, null, null, 'dobradica_quadril', 'por_halter', 'Em pé com um halter em cada mão à frente das coxas, joelhos levemente dobrados. Empurre o quadril para trás descendo os halteres rente às pernas e volte estendendo o quadril. Mantenha a coluna neutra o tempo todo.', 'proprio', null, 'proprio', null),
    ('stiff_unilateral_halter', 'Stiff unilateral com halter', 'stiff', 'posterior_coxa', array['gluteos', 'lombar']::text[], 'halteres', null, null, null, 'dobradica_quadril', 'por_halter', 'Em pé numa perna só com o halter na mão oposta. Incline o tronco à frente levando a outra perna para trás em linha com o corpo e volte. Quadril nivelado, sem girar para o lado.', 'proprio', null, 'proprio', null),
    ('flexao_nordica', 'Flexão nórdica', 'flexao_nordica', 'posterior_coxa', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_joelho', 'peso_corporal', 'Ajoelhado com os calcanhares presos, corpo reto dos joelhos à cabeça. Incline o corpo à frente o mais devagar possível usando o posterior para frear e apare a queda com as mãos. Volte empurrando com as mãos até conseguir subir sozinho.', 'proprio', null, 'proprio', null),
    ('elevacao_pelvica_barra', 'Elevação pélvica com barra', 'elevacao_pelvica', 'gluteos', array['posterior_coxa']::text[], 'barra', null, null, null, 'extensao_quadril', 'total', 'Com a parte alta das costas apoiada no banco e a barra sobre o quadril, pés firmes no chão. Suba o quadril até o tronco ficar alinhado com as coxas, contraia o glúteo e desça controlando. Evite arquear a lombar no topo.', 'proprio', null, 'proprio', null),
    ('elevacao_pelvica_maquina', 'Elevação pélvica na máquina', 'elevacao_pelvica', 'gluteos', array['posterior_coxa']::text[], 'maquina', null, null, null, 'extensao_quadril', 'total', 'Na máquina de elevação pélvica com as costas no apoio e o cinto ou rolo sobre o quadril. Suba o quadril até o alinhamento com as coxas e desça devagar. Ajuste os pés para a canela ficar vertical no topo.', 'proprio', null, 'proprio', null),
    ('elevacao_pelvica_smith', 'Elevação pélvica no smith', 'elevacao_pelvica', 'gluteos', array['posterior_coxa']::text[], 'maquina', null, null, null, 'extensao_quadril', 'total', 'Com as costas no banco e a barra guiada sobre o quadril, suba até o tronco alinhar com as coxas e desça controlando. A barra guiada facilita montar a carga. Use protetor sobre o quadril.', 'proprio', null, 'proprio', null),
    ('elevacao_pelvica_unilateral', 'Elevação pélvica unilateral', 'elevacao_pelvica', 'gluteos', array['posterior_coxa']::text[], 'peso_corporal', null, null, null, 'extensao_quadril', 'peso_corporal', 'Com a parte alta das costas no banco e um pé só no chão, a outra perna elevada. Suba o quadril até alinhar com a coxa de apoio e desça devagar. Mantenha o quadril nivelado, sem cair para um lado.', 'proprio', null, 'proprio', null),
    ('ponte_gluteo', 'Ponte de glúteo no solo', 'elevacao_pelvica', 'gluteos', array['posterior_coxa']::text[], 'peso_corporal', null, null, null, 'extensao_quadril', 'peso_corporal', 'Deitado de costas com os joelhos dobrados e os pés no chão. Suba o quadril até alinhar com as coxas, contraia o glúteo e desça devagar. Empurre pelos calcanhares.', 'proprio', null, 'proprio', null),
    ('gluteo_polia', 'Glúteo na polia (coice)', 'gluteo_coice', 'gluteos', array['posterior_coxa']::text[], 'cabo', null, null, null, 'extensao_quadril', 'total', 'De frente para a polia baixa com a caneleira presa no tornozelo, apoie as mãos na estrutura. Leve a perna para trás estendendo o quadril e volte devagar. Não arqueie a lombar para levar a perna mais alto.', 'proprio', null, 'proprio', null),
    ('gluteo_maquina', 'Glúteo na máquina (coice)', 'gluteo_coice', 'gluteos', array['posterior_coxa']::text[], 'maquina', null, null, null, 'extensao_quadril', 'total', 'Na máquina de glúteo com o peito e os antebraços apoiados, pé na plataforma. Empurre para trás estendendo o quadril e volte controlando. Mantenha o tronco parado.', 'proprio', null, 'proprio', null),
    ('gluteo_quatro_apoios', 'Coice de glúteo em quatro apoios', 'gluteo_coice', 'gluteos', array['posterior_coxa']::text[], 'peso_corporal', null, null, null, 'extensao_quadril', 'peso_corporal', 'Em quatro apoios, joelhos sob o quadril e mãos sob os ombros. Leve uma perna para trás e para cima estendendo o quadril e volte devagar. Mantenha o abdômen firme para a lombar não arquear.', 'proprio', null, 'proprio', null),
    ('cadeira_abdutora', 'Cadeira abdutora', 'abdutora', 'abdutores', array['gluteos']::text[], 'maquina', null, null, null, 'abducao_quadril', 'total', 'Sentado com as costas apoiadas e as almofadas por fora dos joelhos. Afaste as pernas até o fim do movimento e volte devagar sem deixar as placas baterem. Inclinar o tronco à frente aumenta o trabalho do glúteo.', 'proprio', null, 'proprio', null),
    ('cadeira_adutora', 'Cadeira adutora', 'adutora', 'adutores', '{}'::text[], 'maquina', null, null, null, 'aducao_quadril', 'total', 'Sentado com as costas apoiadas e as almofadas por dentro dos joelhos. Feche as pernas até o fim do movimento e volte devagar até alongar. Comece com amplitude menor e aumente aos poucos.', 'proprio', null, 'proprio', null),
    ('abducao_quadril_polia', 'Abdução de quadril na polia', 'abdutora', 'abdutores', array['gluteos']::text[], 'cabo', null, null, null, 'abducao_quadril', 'total', 'De lado para a polia baixa com a caneleira no tornozelo de fora, segure na estrutura. Afaste a perna para o lado e volte controlando. Mantenha o tronco reto, sem inclinar para o lado.', 'proprio', null, 'proprio', null),
    ('aducao_quadril_polia', 'Adução de quadril na polia', 'adutora', 'adutores', '{}'::text[], 'cabo', null, null, null, 'aducao_quadril', 'total', 'De lado para a polia baixa com a caneleira no tornozelo de dentro, segure na estrutura. Traga a perna para dentro cruzando à frente da outra e volte devagar. Mantenha o quadril parado.', 'proprio', null, 'proprio', null),
    ('swing_kettlebell', 'Swing com kettlebell', 'swing', 'gluteos', array['posterior_coxa', 'lombar', 'abdomen']::text[], 'kettlebell', null, null, null, 'dobradica_quadril', 'total', 'Com os pés um pouco além da largura dos ombros, segure o kettlebell com as duas mãos. Leve-o entre as pernas empurrando o quadril para trás e projete o quadril à frente com força para o kettlebell subir até a altura do peito. O movimento é de quadril, não de agachamento nem de braço.', 'proprio', null, 'proprio', null),
    ('panturrilha_em_pe_maquina', 'Panturrilha em pé na máquina', 'panturrilha_em_pe', 'panturrilha', '{}'::text[], 'maquina', null, null, null, 'flexao_plantar', 'total', 'Em pé na máquina com os ombros sob as almofadas e a ponta dos pés na borda do degrau. Desça os calcanhares até alongar e suba o máximo que conseguir na ponta dos pés. Segure um instante no alto e no fundo, sem quicar.', 'proprio', null, 'proprio', null),
    ('panturrilha_sentado', 'Panturrilha sentado na máquina', 'panturrilha_sentado', 'panturrilha', '{}'::text[], 'maquina', null, null, null, 'flexao_plantar', 'total', 'Sentado com a almofada sobre os joelhos e a ponta dos pés na plataforma. Desça os calcanhares até alongar e suba na ponta dos pés. Com o joelho dobrado o trabalho vai mais para o sóleo.', 'proprio', null, 'proprio', null),
    ('panturrilha_leg_press', 'Panturrilha no leg press', 'panturrilha_em_pe', 'panturrilha', '{}'::text[], 'maquina', null, null, null, 'flexao_plantar', 'total', 'No leg press com a ponta dos pés na borda baixa da plataforma e os joelhos estendidos sem travar. Empurre com a ponta dos pés e volte até alongar. Não destrave a máquina para a plataforma não descer sobre você.', 'proprio', null, 'proprio', null),
    ('panturrilha_smith', 'Panturrilha em pé no smith', 'panturrilha_em_pe', 'panturrilha', '{}'::text[], 'maquina', null, null, null, 'flexao_plantar', 'total', 'Com a barra guiada no trapézio e a ponta dos pés sobre uma anilha ou degrau. Desça os calcanhares até alongar e suba o máximo na ponta dos pés. A barra guiada ajuda no equilíbrio.', 'proprio', null, 'proprio', null),
    ('panturrilha_unilateral_halter', 'Panturrilha unilateral com halter', 'panturrilha_em_pe', 'panturrilha', '{}'::text[], 'halteres', null, null, null, 'flexao_plantar', 'por_halter', 'Em pé num degrau com um pé só, halter na mão do mesmo lado e a outra mão apoiada. Desça o calcanhar até alongar e suba na ponta do pé. Faça a série inteira de um lado e troque.', 'proprio', null, 'proprio', null),
    ('panturrilha_peso_corporal', 'Panturrilha em pé sem carga', 'panturrilha_em_pe', 'panturrilha', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_plantar', 'peso_corporal', 'Em pé com a ponta dos pés num degrau e as mãos apoiadas. Desça os calcanhares até alongar e suba o máximo na ponta dos pés. Aumente a dificuldade fazendo com uma perna só.', 'proprio', null, 'proprio', null),
    ('elevacao_tibial', 'Elevação de tibial', 'tibial', 'tibial', '{}'::text[], 'peso_corporal', null, null, null, 'dorsiflexao', 'peso_corporal', 'Encostado na parede com os calcanhares um pouco à frente do corpo. Levante a ponta dos pés o máximo que conseguir, mantendo os calcanhares no chão, e desça devagar. Quanto mais longe da parede, mais difícil.', 'proprio', null, 'proprio', null),
    ('abdominal_supra', 'Abdominal supra no solo', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Deitado de costas com os joelhos dobrados e os pés no chão, mãos atrás da cabeça ou cruzadas no peito. Enrole o tronco tirando as escápulas do chão e desça devagar. Não puxe a cabeça com as mãos.', 'proprio', null, 'proprio', null),
    ('abdominal_infra', 'Abdominal infra no solo', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Deitado de costas com as mãos sob o quadril e as pernas estendidas ou dobradas. Eleve as pernas tirando o quadril do chão no fim e desça devagar sem encostar os pés. Mantenha a lombar colada no chão.', 'proprio', null, 'proprio', null),
    ('elevacao_pernas_suspenso', 'Elevação de pernas suspenso na barra', 'abdominal_suspenso', 'abdomen', array['antebraco']::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Pendurado na barra fixa, eleve as pernas estendidas ou os joelhos dobrados até a altura do quadril ou mais, enrolando a pelve. Desça devagar sem balançar. O movimento vem do abdômen, não do impulso.', 'proprio', null, 'proprio', null),
    ('elevacao_joelhos_paralelas', 'Elevação de joelhos na paralela', 'abdominal_suspenso', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Apoiado nos antebraços no aparelho de paralela com as costas no encosto. Eleve os joelhos em direção ao peito enrolando a pelve e desça devagar. Não balance as pernas para ganhar impulso.', 'proprio', null, 'proprio', null),
    ('abdominal_polia', 'Abdominal na polia com corda', 'abdominal', 'abdomen', '{}'::text[], 'cabo', null, null, 'corda', 'flexao_tronco', 'total', 'Ajoelhado de frente para a polia alta, segure a corda ao lado da cabeça. Enrole o tronco levando os cotovelos em direção aos joelhos e volte devagar. O quadril fica parado, quem se move é o tronco.', 'proprio', null, 'proprio', null),
    ('abdominal_maquina', 'Abdominal na máquina', 'abdominal', 'abdomen', '{}'::text[], 'maquina', null, null, null, 'flexao_tronco', 'total', 'Sentado na máquina de abdominal com as almofadas no peito ou as pegadas nas mãos. Enrole o tronco à frente e volte devagar. Evite puxar com os braços.', 'proprio', null, 'proprio', null),
    ('abdominal_obliquo', 'Abdominal oblíquo', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Deitado de costas com os joelhos dobrados, mãos atrás da cabeça. Enrole o tronco levando um ombro em direção ao joelho oposto e alterne os lados. Não puxe o pescoço.', 'proprio', null, 'proprio', null),
    ('abdominal_bicicleta', 'Abdominal bicicleta', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Deitado com as mãos atrás da cabeça e as pernas elevadas. Leve um cotovelo em direção ao joelho oposto enquanto estende a outra perna, e alterne como se pedalasse. Faça devagar, sem pressa.', 'proprio', null, 'proprio', null),
    ('abdominal_declinado', 'Abdominal no banco declinado', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'No banco declinado com os pés presos, mãos no peito ou atrás da cabeça. Enrole o tronco subindo até perto das coxas e desça devagar. Segurar uma anilha no peito aumenta a carga.', 'proprio', null, 'proprio', null),
    ('abdominal_remador', 'Abdominal remador', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Sentado no chão com as pernas estendidas e o tronco inclinado para trás. Traga os joelhos ao peito ao mesmo tempo que aproxima o tronco e volte estendendo. Mantenha o equilíbrio sobre o glúteo.', 'proprio', null, 'proprio', null),
    ('abdominal_canivete', 'Abdominal canivete', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'flexao_tronco', 'peso_corporal', 'Deitado de costas com braços e pernas estendidos. Suba tronco e pernas ao mesmo tempo tentando tocar as mãos nos pés e desça devagar. Dobrar levemente os joelhos facilita.', 'proprio', null, 'proprio', null),
    ('roda_abdominal', 'Roda abdominal', 'roda_abdominal', 'abdomen', array['ombro_anterior', 'costas']::text[], 'outro', null, null, null, 'antiextensao', 'peso_corporal', 'Ajoelhado segurando a roda à frente dos joelhos. Role à frente estendendo o corpo até onde conseguir manter a lombar sem arquear e volte puxando com o abdômen. Comece com amplitude curta.', 'proprio', null, 'proprio', null),
    ('prancha', 'Prancha frontal', 'prancha', 'abdomen', array['ombro_anterior']::text[], 'peso_corporal', null, null, null, 'antiextensao', 'peso_corporal', 'Apoiado nos antebraços e na ponta dos pés, corpo alinhado da cabeça aos calcanhares. Mantenha a posição pelo tempo prescrito com abdômen e glúteo contraídos. Não deixe o quadril cair nem subir demais.', 'proprio', null, 'proprio', null),
    ('prancha_lateral', 'Prancha lateral', 'prancha', 'abdomen', array['abdutores']::text[], 'peso_corporal', null, null, null, 'antirrotacao', 'peso_corporal', 'Deitado de lado apoiado no antebraço, cotovelo sob o ombro e pernas estendidas uma sobre a outra. Suba o quadril até o corpo ficar alinhado e mantenha pelo tempo prescrito. Faça os dois lados.', 'proprio', null, 'proprio', null),
    ('prancha_copenhagen_curta', 'Prancha Copenhagen com alavanca curta', 'prancha_copenhagen', 'adutores', array['abdomen']::text[], 'peso_corporal', null, null, null, 'aducao_quadril', 'peso_corporal', 'De lado apoiado no antebraço, com o joelho de cima apoiado num banco e a perna de baixo solta. Suba o quadril até alinhar o corpo e mantenha. Apoiar o joelho em vez do pé deixa o exercício mais leve.', 'proprio', null, 'proprio', null),
    ('prancha_copenhagen_longa', 'Prancha Copenhagen com alavanca longa', 'prancha_copenhagen', 'adutores', array['abdomen']::text[], 'peso_corporal', null, null, null, 'aducao_quadril', 'peso_corporal', 'De lado apoiado no antebraço, com o pé de cima apoiado num banco e a perna estendida. Suba o quadril até alinhar o corpo e mantenha. É a versão mais pesada para os adutores.', 'proprio', null, 'proprio', null),
    ('dead_bug', 'Dead bug', 'antiextensao', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'antiextensao', 'peso_corporal', 'Deitado de costas com braços estendidos para o teto e joelhos dobrados a 90 graus no ar. Estenda um braço para trás e a perna oposta à frente sem tirar a lombar do chão e volte. Alterne os lados devagar.', 'proprio', null, 'proprio', null),
    ('bird_dog', 'Bird dog (perdigueiro)', 'antiextensao', 'lombar', array['gluteos', 'abdomen']::text[], 'peso_corporal', null, null, null, 'antiextensao', 'peso_corporal', 'Em quatro apoios, estenda um braço à frente e a perna oposta para trás até ficarem alinhados com o tronco. Segure um instante e volte, alternando os lados. Mantenha o quadril nivelado e as costas paradas.', 'proprio', null, 'proprio', null),
    ('pallof_press', 'Pallof press na polia', 'antirrotacao', 'abdomen', '{}'::text[], 'cabo', null, null, null, 'antirrotacao', 'total', 'De lado para a polia na altura do peito, segure a alça com as duas mãos junto ao peito. Empurre as mãos à frente resistindo à rotação do tronco, segure e volte. Faça os dois lados.', 'proprio', null, 'proprio', null),
    ('lenhador_alto_baixo', 'Lenhador na polia de cima para baixo', 'lenhador', 'abdomen', array['ombro_anterior']::text[], 'cabo', null, null, null, 'rotacao', 'total', 'De lado para a polia alta, segure a alça com as duas mãos acima do ombro. Puxe em diagonal até o quadril do lado oposto girando o tronco e volte controlando. Os braços ficam quase estendidos, quem gira é o tronco.', 'proprio', null, 'proprio', null),
    ('lenhador_baixo_alto', 'Lenhador na polia de baixo para cima', 'lenhador', 'abdomen', array['ombro_anterior']::text[], 'cabo', null, null, null, 'rotacao', 'total', 'De lado para a polia baixa, segure a alça com as duas mãos ao lado do quadril. Puxe em diagonal até acima do ombro oposto girando o tronco e volte controlando. Empurre com as pernas no começo do movimento.', 'proprio', null, 'proprio', null),
    ('rotacao_russa', 'Rotação russa', 'abdominal', 'abdomen', '{}'::text[], 'peso_corporal', null, null, null, 'rotacao', 'peso_corporal', 'Sentado com o tronco inclinado para trás e os pés no chão ou elevados, mãos juntas à frente. Gire o tronco levando as mãos de um lado ao outro do quadril. Segurar uma anilha ou halter aumenta a carga.', 'proprio', null, 'proprio', null),
    ('escalador', 'Escalador', 'escalador', 'abdomen', array['quadriceps', 'ombro_anterior']::text[], 'peso_corporal', null, null, null, 'antiextensao', 'peso_corporal', 'Em prancha alta com as mãos sob os ombros, traga um joelho em direção ao peito e troque as pernas rapidamente. Mantenha o quadril baixo e os ombros sobre as mãos. Ritmo constante pelo tempo prescrito.', 'proprio', null, 'proprio', null),
    ('burpee', 'Burpee', 'burpee', 'quadriceps', array['peito', 'ombro_anterior', 'abdomen']::text[], 'peso_corporal', null, null, null, 'corpo_inteiro', 'peso_corporal', 'Em pé, agache e apoie as mãos no chão, jogue os pés para trás até a prancha, volte os pés para perto das mãos e salte para cima. Pode incluir uma flexão na prancha. Mantenha o abdômen firme para não cair o quadril.', 'proprio', null, 'proprio', null),
    ('caminhada_fazendeiro', 'Caminhada do fazendeiro com halteres', 'carregamento', 'antebraco', array['trapezio', 'abdomen']::text[], 'halteres', null, null, null, 'carregamento', 'por_halter', 'Em pé com um halter pesado em cada mão ao lado do corpo. Caminhe com passos curtos, tronco ereto e ombros para trás pela distância ou tempo prescrito. Não deixe os ombros caírem para frente.', 'proprio', null, 'proprio', null),
    ('carregamento_mala', 'Carregamento unilateral com halter (suitcase carry)', 'carregamento', 'abdomen', array['antebraco', 'trapezio']::text[], 'halteres', null, null, null, 'carregamento', 'por_halter', 'Em pé com um halter numa mão só, como quem carrega uma mala. Caminhe mantendo o tronco reto, sem inclinar para o lado do peso, e troque de mão na volta. Trabalha muito a lateral do abdômen.', 'proprio', null, 'proprio', null),
    ('sustentacao_mala', 'Sustentação unilateral com halter (suitcase hold)', 'carregamento', 'abdomen', array['antebraco', 'trapezio']::text[], 'halteres', null, null, null, 'carregamento', 'por_halter', 'Em pé parado com um halter pesado numa mão só ao lado do corpo. Mantenha o tronco reto sem inclinar pelo tempo prescrito e troque de mão. É o carregamento de mala sem caminhar.', 'proprio', null, 'proprio', null),
    ('puxada_frontal_fechada', 'Puxada frontal pronada fechada', 'puxada', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', 'pronada', 'fechada', 'barra_reta', 'puxar_vertical', 'total', 'Sentado com as coxas presas, segure a barra reta com pegada pronada na largura dos ombros ou um pouco menos. Puxe até a parte alta do peito com os cotovelos à frente do tronco e volte estendendo os braços. A pegada fechada aumenta a amplitude e o trabalho do bíceps.', 'proprio', null, 'proprio', null),
    ('puxada_neutra_media', 'Puxada neutra média', 'puxada', 'costas', array['biceps']::text[], 'cabo', 'neutra', 'media', 'barra_neutra', 'puxar_vertical', 'total', 'Sentado na puxada com a barra de pegada neutra na largura dos ombros, palmas voltadas uma para a outra. Puxe até o peito levando os cotovelos para baixo e volte devagar. Fica entre o triângulo e a neutra aberta em amplitude.', 'proprio', null, 'proprio', null),
    ('remada_baixa_supinada', 'Remada baixa supinada', 'remada_baixa', 'costas', array['biceps']::text[], 'cabo', 'supinada', 'media', 'barra_reta', 'puxar_horizontal', 'total', 'Sentado na remada baixa com a barra reta presa ao cabo, palmas para cima na largura dos ombros. Puxe até o abdômen com os cotovelos junto ao corpo e volte alongando. Mais bíceps e parte baixa das costas que a versão aberta.', 'proprio', null, 'proprio', null),
    ('remada_baixa_corda', 'Remada baixa com corda', 'remada_baixa', 'costas', array['ombro_posterior', 'biceps']::text[], 'cabo', 'neutra', null, 'corda', 'puxar_horizontal', 'total', 'Sentado na remada baixa com a corda presa ao cabo, segure as pontas. Puxe em direção ao abdômen separando as mãos no fim e volte devagar. A corda deixa os punhos girarem livremente.', 'proprio', null, 'proprio', null),
    ('remada_baixa_unilateral', 'Remada baixa unilateral na polia', 'remada_baixa', 'costas', array['biceps', 'ombro_posterior']::text[], 'cabo', null, null, 'alca', 'puxar_horizontal', 'total', 'Sentado ou em pé de frente para a polia baixa, segure a alça com uma mão. Puxe o cotovelo para trás junto ao corpo e volte alongando, sem girar o tronco. Faça a série inteira de um lado e troque.', 'proprio', null, 'proprio', null),
    ('triceps_polia_supinado', 'Tríceps na polia com pegada supinada', 'triceps_polia', 'triceps', '{}'::text[], 'cabo', 'supinada', null, 'barra_reta', 'extensao_cotovelo', 'total', 'De frente para a polia alta, segure a barra reta com as palmas para cima e os cotovelos colados ao corpo. Empurre para baixo até estender os cotovelos e volte devagar. Use carga menor que na pegada pronada; o punho não pode dobrar.', 'proprio', null, 'proprio', null),
    ('barra_fixa_assistida_neutra', 'Barra fixa assistida neutra na máquina', 'barra_fixa', 'costas', array['biceps']::text[], 'maquina', 'neutra', null, null, 'puxar_vertical', 'assistencia', 'Na máquina de assistência, segure as pegadas paralelas com as palmas voltadas uma para a outra. Puxe até o queixo passar as pegadas e desça controlando. A carga ajuda a subir, então progresso é conseguir usar menos carga.', 'proprio', null, 'proprio', null)
