-- Gerado por `npm run exercises:seed-sql` a partir de supabase/seed/exercises/.
-- Não editar à mão: mudar os JSON da pasta e gerar uma migração nova.
-- Conteúdo próprio (nomes, apelidos e descrições escritos para o app).

on conflict (slug) where owner_user_id is null do update set
    name_pt = excluded.name_pt,
    family = excluded.family,
    primary_muscle = excluded.primary_muscle,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    pegada = excluded.pegada,
    largura_pegada = excluded.largura_pegada,
    acessorio = excluded.acessorio,
    padrao_movimento = excluded.padrao_movimento,
    default_load_form = excluded.default_load_form,
    description_pt = excluded.description_pt,
    source = excluded.source,
    source_ref = excluded.source_ref,
    license = excluded.license,
    attribution = excluded.attribution;

create temporary table seed_exercise_aliases (alias text, slug text);

delete from exercise_aliases a
where a.owner_user_id is null
    and a.alias_norm not in (select normalize_exercise_name(s.alias) from seed_exercise_aliases s);

select e.id, null, s.alias
from seed_exercise_aliases s
join exercises e on e.slug = s.slug and e.owner_user_id is null
on conflict (alias_norm) where owner_user_id is null do update set
    exercise_id = excluded.exercise_id,
    alias = excluded.alias;

drop table seed_exercise_aliases;

delete from exercise_generic_names where name_norm not in ('pulldown', 'pull down', 'puxada', 'puxada frontal', 'puxada frente', 'puxador', 'puxador frente', 'puxador frente pronado', 'puxada alta', 'lat pulldown', 'puxador neutro', 'puxada neutra', 'pulldown neutro', 'pulldown pegada neutra', 'remada baixa', 'remada baixa cabo', 'remada baixa no cabo', 'remada sentada no cabo', 'remada no pulley', 'remada baixa neutra', 'remada sentada', 'triceps polia', 'triceps na polia', 'triceps pulley', 'triceps pulldown', 'triceps barra', 'triceps polia barra', 'rosca direta', 'rosca com barra', 'rosca direta barra', 'barra fixa assistida', 'barra assistida', 'gravitron', 'graviton', 'flexora', 'leg curl', 'desenvolvimento', 'desenvolvimento ombro', 'elevacao frontal', 'supino inclinado', 'trapezio', 'antebraco', 'panturrilha', 'gemeos');

on conflict (name_norm) do update set
    name = excluded.name,
    families = excluded.families;

update workout_sets ws
set exercise_id = resolve_exercise_id(s.user_id, item ->> 'catalogo', item ->> 'nome')
from workout_sessions s
cross join lateral jsonb_array_elements(coalesce(s.workout_snapshot -> 'exercicios', '[]'::jsonb)) as item
where ws.session_id = s.id and item ->> 'exercise_key' = ws.exercise_key;
